import {
  ANALYSIS_STAGES,
  ANALYSIS_STAGE_ENDS_MS,
  ANALYSIS_TOTAL_MS,
  jobTargetSummary,
  progressAt,
  stageIndexAt,
  type AnalysisReport,
  type AnalysisRun,
  type JobTarget,
  type TargetCreateValues,
} from "@/lib/schemas";
import { buildAnalysisReport } from "@/lib/analysis";
import { sampleTargets } from "./analysis-fixtures";
import { loadWorkspace, type KeyValueStorage } from "./workspace-store";

/**
 * Persistent job targets + analysis runs (PRD §6.4, §6.6, §8.4).
 *
 * Reports are generated by the deterministic engine in `lib/analysis`, so the
 * mock is not "random AI output": the same target and workspace version always
 * produce the same score, requirements and gaps. Staleness is derived on read
 * (report version vs workspace version, PRD §6.8) instead of being stored, so it
 * can never go out of sync.
 */

export const TARGETS_KEY_PREFIX = "riq.targets.";

interface StoredTargets {
  targets: JobTarget[];
  reports: Record<string, AnalysisReport>;
  runs: Record<string, AnalysisRun>;
}

export type Clock = () => string;

const isoClock: Clock = () => new Date().toISOString();

export function targetsKey(userId: string): string {
  return `${TARGETS_KEY_PREFIX}${userId}`;
}

function emptyState(): StoredTargets {
  return { targets: [], reports: {}, runs: {} };
}

export function loadTargets(
  storage: KeyValueStorage,
  userId: string,
): StoredTargets {
  try {
    const raw = storage.getItem(targetsKey(userId));
    if (!raw) return emptyState();
    const parsed = JSON.parse(raw) as StoredTargets;
    if (!parsed || !Array.isArray(parsed.targets)) return emptyState();
    return {
      targets: parsed.targets,
      reports: parsed.reports ?? {},
      runs: parsed.runs ?? {},
    };
  } catch {
    return emptyState();
  }
}

function saveTargets(
  storage: KeyValueStorage,
  userId: string,
  state: StoredTargets,
): void {
  storage.setItem(targetsKey(userId), JSON.stringify(state));
}

/** Current workspace version, used for staleness + report generation. */
function workspaceVersionOf(storage: KeyValueStorage, userId: string): number {
  return loadWorkspace(storage, userId).version;
}

/** Marks a saved analysis stale when the workspace moved on (PRD §6.8). */
export function withStaleness(target: JobTarget, currentVersion: number): JobTarget {
  if (!target.analysis) return target;
  return {
    ...target,
    analysis: {
      ...target.analysis,
      stale: target.analysis.workspaceVersion < currentVersion,
    },
  };
}

export function listTargets(
  storage: KeyValueStorage,
  userId: string,
): JobTarget[] {
  const version = workspaceVersionOf(storage, userId);
  return loadTargets(storage, userId).targets
    .map((target) => withStaleness(target, version))
    .sort((a, b) => b.createdAt.localeCompare(a.createdAt));
}

export function getTarget(
  storage: KeyValueStorage,
  userId: string,
  targetId: string,
): JobTarget | null {
  const target = loadTargets(storage, userId).targets.find(
    (candidate) => candidate.id === targetId,
  );
  if (!target) return null;
  return withStaleness(target, workspaceVersionOf(storage, userId));
}

function slug(value: string): string {
  return (
    value
      .trim()
      .toLowerCase()
      .replace(/[^a-z0-9]+/g, "-")
      .replace(/^-|-$/g, "")
      .slice(0, 24) || "target"
  );
}

export function createTarget(
  storage: KeyValueStorage,
  userId: string,
  input: TargetCreateValues,
  now: Clock = isoClock,
): JobTarget {
  const state = loadTargets(storage, userId);
  const at = now();
  const target: JobTarget = {
    id: `tgt-${slug(input.role)}-${state.targets.length + 1}`,
    role: input.role.trim(),
    company: input.company.trim() || null,
    jobDescription: input.jobDescription.trim(),
    requiredSkills: input.requiredSkills,
    template: input.template,
    length: input.length,
    status: "draft",
    analysis: null,
    sample: false,
    createdAt: at,
    updatedAt: at,
  };
  state.targets = [...state.targets, target];
  saveTargets(storage, userId, state);
  return target;
}

/** Dev-only: writes the three demo targets (PRD §8.5 F4 fixtures). */
export function createSampleTargets(
  storage: KeyValueStorage,
  userId: string,
  now: Clock = isoClock,
): JobTarget[] {
  const state = loadTargets(storage, userId);
  const created = sampleTargets(new Date(now()));
  const existingIds = new Set(state.targets.map((target) => target.id));
  const added = created.filter((target) => !existingIds.has(target.id));
  state.targets = [...state.targets, ...added];
  saveTargets(storage, userId, state);
  return state.targets;
}

/** Stage the simulated provider fails at (dev failure toggle only). */
const FAIL_STAGE_INDEX = 3; // "Matching evidence"
const FAIL_STAGE = ANALYSIS_STAGES[FAIL_STAGE_INDEX].key;

/**
 * Starts (or restarts) a run. A run already inside its window is reused so a
 * double click can't fork the theatre into two animations.
 */
export function startRun(
  storage: KeyValueStorage,
  userId: string,
  targetId: string,
  now: Clock = isoClock,
): AnalysisRun | null {
  const state = loadTargets(storage, userId);
  const target = state.targets.find((candidate) => candidate.id === targetId);
  if (!target) return null;

  const at = now();
  const existing = state.runs[targetId];
  if (
    existing &&
    existing.status === "running" &&
    Date.parse(at) - Date.parse(existing.startedAt) < ANALYSIS_TOTAL_MS + 2_000
  ) {
    return existing;
  }

  const run: AnalysisRun = {
    id: `run-${targetId}-${Date.parse(at)}`,
    targetId,
    status: "running",
    stage: ANALYSIS_STAGES[0].key,
    stageIndex: 0,
    stageCount: ANALYSIS_STAGES.length,
    progress: 0,
    workspaceVersion: workspaceVersionOf(storage, userId),
    startedAt: at,
    updatedAt: at,
    finishedAt: null,
    failure: null,
  };
  target.status = "analyzing";
  delete state.reports[targetId];
  state.runs[targetId] = run;
  saveTargets(storage, userId, state);
  return run;
}

export interface RunState {
  run: AnalysisRun;
  report: AnalysisReport | null;
}

/**
 * Advances a run based on wall-clock time (the mock "provider" works while the
 * theatre polls). Completion generates the deterministic report and records the
 * score summary on the target.
 */
export function advanceRun(
  storage: KeyValueStorage,
  userId: string,
  targetId: string,
  now: Clock = isoClock,
  failures = false,
): RunState | null {
  const state = loadTargets(storage, userId);
  const target = state.targets.find((candidate) => candidate.id === targetId);
  const run = state.runs[targetId];
  if (!target || !run) return null;

  if (run.status === "succeeded") {
    return { run, report: state.reports[targetId] ?? null };
  }
  if (run.status === "failed") {
    return { run, report: null };
  }

  const at = now();
  const elapsed = Math.max(0, Date.parse(at) - Date.parse(run.startedAt));

  // Dev-only "provider is down": the theatre shows a real failed stage and the
  // retry path, rather than the request failing before anything starts.
  const failAt = ANALYSIS_STAGE_ENDS_MS[FAIL_STAGE_INDEX];
  if (failures && elapsed >= failAt) {
    const failed: AnalysisRun = {
      ...run,
      status: "failed",
      stage: FAIL_STAGE,
      stageIndex: FAIL_STAGE_INDEX,
      progress: progressAt(failAt),
      updatedAt: at,
      finishedAt: at,
      failure: {
        code: "provider_unavailable",
        message:
          "The mock analysis provider stopped responding. Nothing was saved. Turn the failure toggle off and retry.",
        stage: FAIL_STAGE,
      },
    };
    target.status = "failed";
    state.runs[targetId] = failed;
    saveTargets(storage, userId, state);
    return { run: failed, report: null };
  }

  if (elapsed >= ANALYSIS_TOTAL_MS) {
    const ws = loadWorkspace(storage, userId);
    const report = buildAnalysisReport({
      target,
      items: ws.items,
      workspaceVersion: ws.version,
      workspaceUpdatedAt: ws.updatedAt,
      generatedAt: at,
    });
    const done: AnalysisRun = {
      ...run,
      status: "succeeded",
      stage: ANALYSIS_STAGES[ANALYSIS_STAGES.length - 1].key,
      stageIndex: ANALYSIS_STAGES.length - 1,
      progress: 100,
      updatedAt: at,
      finishedAt: at,
      failure: null,
    };
    state.runs[targetId] = done;
    state.reports[targetId] = report;
    target.status = "ready";
    target.analysis = jobTargetSummary(report, at);
    saveTargets(storage, userId, state);
    return { run: done, report };
  }

  const index = stageIndexAt(elapsed);
  const running: AnalysisRun = {
    ...run,
    status: "running",
    stage: ANALYSIS_STAGES[index].key,
    stageIndex: index,
    progress: progressAt(elapsed),
    updatedAt: at,
  };
  state.runs[targetId] = running;
  saveTargets(storage, userId, state);
  return { run: running, report: null };
}

export function getReport(
  storage: KeyValueStorage,
  userId: string,
  targetId: string,
): AnalysisReport | null {
  return loadTargets(storage, userId).reports[targetId] ?? null;
}
